read_counts <- function(path) {
  if (dir.exists(path)) {
    x <- Read10X(data.dir = path)
    if (is.list(x)) {
      if ("Gene Expression" %in% names(x)) {
        x <- x[["Gene Expression"]]
      } else if ("RNA" %in% names(x)) {
        x <- x[["RNA"]]
      } else {
        x <- x[[1]]
      }
    }
  } else {
    ext <- tools::file_ext(path)
    if (tolower(ext) == "rds") {
      x <- readRDS(path)
    } else if (tolower(ext) == "csv") {
      x <- read.csv(path, row.names = 1, check.names = FALSE)
      x <- as.matrix(x)
    } else if (tolower(ext) %in% c("tsv", "txt")) {
      x <- read.delim(path, row.names = 1, check.names = FALSE)
      x <- as.matrix(x)
    } else {
      stop(paste("Unsupported file:", path))
    }
  }
  if (!inherits(x, "dgCMatrix")) {
    x <- as(as.matrix(x), "dgCMatrix")
  }
  rownames(x) <- make.unique(rownames(x))
  colnames(x) <- make.unique(colnames(x))
  x
}

