parse_args <- function(x) {
  out <- list()
  i <- 1
  while (i <= length(x)) {
    a <- x[[i]]
    if (grepl("^--", a)) {
      a <- sub("^--", "", a)
      if (grepl("=", a, fixed = TRUE)) {
        kv <- strsplit(a, "=", fixed = TRUE)[[1]]
        out[[kv[[1]]]] <- paste(kv[-1], collapse = "=")
      } else {
        if (i < length(x) && !grepl("^--", x[[i + 1]])) {
          out[[a]] <- x[[i + 1]]
          i <- i + 1
        } else {
          out[[a]] <- "TRUE"
        }
      }
    }
    i <- i + 1
  }
  out
}

cli <- parse_args(commandArgs(trailingOnly = TRUE))

cfg_get <- function(key, default = NULL) {
  env_key <- toupper(gsub("[.-]", "_", key))
  if (!is.null(cli[[key]])) return(cli[[key]])
  val <- Sys.getenv(env_key, unset = NA_character_)
  if (!is.na(val) && nzchar(val)) return(val)
  default
}

as_bool <- function(x) {
  if (is.logical(x)) return(x)
  tolower(as.character(x)) %in% c("true", "t", "1", "yes", "y")
}

