read_input_one <- function(path) {
  if (!file.exists(path)) stop("Input does not exist: ", path)
  if (dir.exists(path)) {
    x <- Seurat::Read10X(data.dir = path)
    if (is.list(x)) {
      if ("Gene Expression" %in% names(x)) x <- x[["Gene Expression"]] else x <- x[[1]]
    }
    return(x)
  }
  ext <- tolower(basename(path))
  if (grepl("\\.rds$", ext)) {
    return(readRDS(path))
  }
  if (grepl("\\.h5$", ext) || grepl("\\.hdf5$", ext)) {
    x <- Seurat::Read10X_h5(filename = path)
    if (is.list(x)) {
      if ("Gene Expression" %in% names(x)) x <- x[["Gene Expression"]] else x <- x[[1]]
    }
    return(x)
  }
  if (grepl("\\.mtx(\\.gz)?$", ext)) {
    m <- Matrix::readMM(path)
    base_dir <- dirname(path)
    barcodes <- c(file.path(base_dir, "barcodes.tsv.gz"), file.path(base_dir, "barcodes.tsv"))
    features <- c(file.path(base_dir, "features.tsv.gz"), file.path(base_dir, "features.tsv"), file.path(base_dir, "genes.tsv.gz"), file.path(base_dir, "genes.tsv"))
    barcode_file <- barcodes[file.exists(barcodes)][1]
    feature_file <- features[file.exists(features)][1]
    if (!is.na(barcode_file)) colnames(m) <- read.table(barcode_file, sep = "\t", header = FALSE, stringsAsFactors = FALSE)[[1]]
    if (!is.na(feature_file)) {
      ft <- read.table(feature_file, sep = "\t", header = FALSE, stringsAsFactors = FALSE)
      rownames(m) <- make.unique(if (ncol(ft) >= 2) ft[[2]] else ft[[1]])
    }
    return(as(m, "dgCMatrix"))
  }
  if (grepl("\\.csv(\\.gz)?$", ext)) {
    return(as(as.matrix(read.csv(path, row.names = 1, check.names = FALSE)), "dgCMatrix"))
  }
  if (grepl("\\.tsv(\\.gz)?$|\\.txt(\\.gz)?$", ext)) {
    return(as(as.matrix(read.delim(path, row.names = 1, check.names = FALSE)), "dgCMatrix"))
  }
  stop("Unsupported input format: ", path)
}

inputs <- trimws(unlist(strsplit(config$input, ",")))
sample_names <- trimws(unlist(strsplit(config$sample_names, ",")))
if (length(sample_names) != length(inputs) || any(!nzchar(sample_names))) {
  sample_names <- make.unique(ifelse(nzchar(basename(inputs)), tools::file_path_sans_ext(basename(inputs)), paste0("sample", seq_along(inputs))))
}

objects <- vector("list", length(inputs))
for (i in seq_along(inputs)) {
  loaded <- read_input_one(inputs[[i]])
  if (inherits(loaded, "Seurat")) {
    obj_i <- loaded
    obj_i$orig.ident <- sample_names[[i]]
  } else {
    obj_i <- CreateSeuratObject(
      counts = loaded,
      project = sample_names[[i]],
      min.cells = config$min_cells,
      min.features = config$min_features
    )
    obj_i$orig.ident <- sample_names[[i]]
  }
  objects[[i]] <- obj_i
}

obj <- if (length(objects) == 1) {
  objects[[1]]
} else {
  merge(objects[[1]], y = objects[-1], add.cell.ids = sample_names, project = config$project)
}

