save_plot <- function(plot, filename, width = 10, height = 7, dpi = 300) {
  png_file <- file.path(config$outdir, "plots", paste0(filename, ".png"))
  pdf_file <- file.path(config$outdir, "plots", paste0(filename, ".pdf"))
  dir.create(dirname(png_file), recursive = TRUE, showWarnings = FALSE)
  ggplot2::ggsave(png_file, plot = plot, width = width, height = height, dpi = dpi, limitsize = FALSE)
  ggplot2::ggsave(pdf_file, plot = plot, width = width, height = height, limitsize = FALSE)
}

safe_percentage <- function(object, pattern, col.name) {
  feats <- grep(pattern, rownames(object), value = TRUE)
  if (length(feats) > 0) {
    object[[col.name]] <- PercentageFeatureSet(object, features = feats)
  } else {
    object[[col.name]] <- 0
  }
  object
}

