    sce <- as.SingleCellExperiment(obj)
    if (is.na(config$doublet_rate)) {
      sce <- scDblFinder::scDblFinder(sce, samples = "orig.ident")
    } else {
      sce <- scDblFinder::scDblFinder(sce, samples = "orig.ident", dbr = config$doublet_rate)
    }
    cd <- as.data.frame(SingleCellExperiment::colData(sce))
    dbl_cols <- intersect(c("scDblFinder.class", "scDblFinder.score"), colnames(cd))
    for (ccol in dbl_cols) obj[[ccol]] <- cd[colnames(obj), ccol, drop = TRUE]
    write.csv(obj@meta.data[, intersect(c("orig.ident", "scDblFinder.class", "scDblFinder.score"), colnames(obj@meta.data)), drop = FALSE], file.path(config$outdir, "tables/qc", "doublet_detection.csv"))
    if (config$remove_doublets && "scDblFinder.class" %in% colnames(obj@meta.data)) {
      before_doublet_filter <- colnames(obj)
      obj <- subset(obj, subset = scDblFinder.class != "doublet")
      write.csv(data.frame(cell = setdiff(before_doublet_filter, colnames(obj))), file.path(config$outdir, "tables/qc", "cells_removed_as_doublets.csv"), row.names = FALSE)
    }
  }, silent = FALSE)
}

