if (length(pbmc_gene_sets) > 0) {
  obj <- AddModuleScore(obj, features = pbmc_gene_sets, name = "PBMC_Module_", seed = config$seed)
  score_cols <- paste0("PBMC_Module_", seq_along(pbmc_gene_sets))
  score_cols <- intersect(score_cols, colnames(obj@meta.data))
  names(score_cols) <- names(pbmc_gene_sets)[seq_along(score_cols)]
  score_matrix <- as.matrix(obj@meta.data[, score_cols, drop = FALSE])
  colnames(score_matrix) <- names(score_cols)
  obj$predicted_cell_type_module <- colnames(score_matrix)[max.col(score_matrix, ties.method = "first")]
  cluster_scores <- aggregate(score_matrix, by = list(cluster = obj$seurat_clusters), FUN = mean)
  rownames(cluster_scores) <- cluster_scores$cluster
  cluster_scores$cluster <- NULL
  cluster_annotations <- colnames(cluster_scores)[max.col(as.matrix(cluster_scores), ties.method = "first")]
  names(cluster_annotations) <- rownames(cluster_scores)
  obj$cluster_cell_type_module <- unname(cluster_annotations[as.character(obj$seurat_clusters)])
  write.csv(data.frame(cluster = names(cluster_annotations), annotation = cluster_annotations), file.path(config$outdir, "tables", "cluster_module_annotations.csv"), row.names = FALSE)
  write.csv(cluster_scores, file.path(config$outdir, "tables", "cluster_module_scores.csv"))
  p_umap_annot <- DimPlot(obj, reduction = "umap", group.by = "cluster_cell_type_module", label = TRUE, repel = TRUE) + ggtitle("UMAP by module-score annotation")
  save_plot(p_umap_annot, "dimensions/umap_module_annotations", width = 11, height = 8)
}

