parse_args <- function(args) {
  defaults <- list(
    input = Sys.getenv("SCRNA_INPUT", "filtered_feature_bc_matrix"),
    output = Sys.getenv("SCRNA_OUTPUT", "seurat_pbmc_outputs"),
    project = Sys.getenv("SCRNA_PROJECT", "PBMC"),
    min_cells = 3,
    min_features = 200,
    max_features = NA_real_,
    min_counts = NA_real_,
    max_counts = NA_real_,
    max_percent_mt = 20,
    max_percent_hb = 5,
    nfeatures = 2000,
    npcs = 50,
    dims = NA_character_,
    resolution = 0.8,
    regress_mt = TRUE,
    regress_counts = TRUE,
    run_doublets = TRUE,
    remove_doublets = FALSE,
    run_sctransform = FALSE,
    organism = "human"
  )
  if (length(args) == 0) return(defaults)
  i <- 1
  while (i <= length(args)) {
    a <- args[[i]]
    if (grepl("^--", a)) {
      kv <- sub("^--", "", a)
      if (grepl("=", kv, fixed = TRUE)) {
        sp <- strsplit(kv, "=", fixed = TRUE)[[1]]
        key <- sp[[1]]
        val <- paste(sp[-1], collapse = "=")
      } else {
        key <- kv
        if (i == length(args) || grepl("^--", args[[i + 1]])) {
          val <- "TRUE"
        } else {
          val <- args[[i + 1]]
          i <- i + 1
        }
      }
      if (key %in% names(defaults)) defaults[[key]] <- val
    }
    i <- i + 1
  }
  numeric_keys <- c("min_cells", "min_features", "max_features", "min_counts", "max_counts",
                    "max_percent_mt", "max_percent_hb", "nfeatures", "npcs", "resolution")
  logical_keys <- c("regress_mt", "regress_counts", "run_doublets", "remove_doublets", "run_sctransform")
  for (k in numeric_keys) defaults[[k]] <- suppressWarnings(as.numeric(defaults[[k]]))
  for (k in logical_keys) defaults[[k]] <- tolower(as.character(defaults[[k]])) %in% c("true", "t", "1", "yes", "y")
  defaults
}

