read_counts <- function(input) {
  if (dir.exists(input)) {
    files <- list.files(input, full.names = FALSE)
    if (any(grepl("matrix\\.mtx(\\.gz)?$", files)) &&
        any(grepl("(features|genes)\\.tsv(\\.gz)?$", files)) &&
        any(grepl("barcodes\\.tsv(\\.gz)?$", files))) {
      x <- Seurat::Read10X(data.dir = input)
    } else {
      h5s <- list.files(input, pattern = "\\.h5$", full.names = TRUE)
      if (length(h5s) == 1) {
        x <- Seurat::Read10X_h5(h5s[[1]])
      } else {
        stop("Directory input must be a 10X matrix directory or contain exactly one .h5 file.", call. = FALSE)
      }
    }
  } else if (grepl("\\.h5$", input, ignore.case = TRUE)) {
    x <- Seurat::Read10X_h5(input)
  } else if (grepl("\\.rds$", input, ignore.case = TRUE)) {
    x <- readRDS(input)
    if (inherits(x, "Seurat")) return(x)
  } else if (grepl("\\.csv(\\.gz)?$", input, ignore.case = TRUE)) {
    x <- read.csv(input, row.names = 1, check.names = FALSE)
    x <- as(as.matrix(x), "dgCMatrix")
  } else if (grepl("\\.tsv(\\.gz)?$|\\.txt(\\.gz)?$", input, ignore.case = TRUE)) {
    x <- read.delim(input, row.names = 1, check.names = FALSE)
    x <- as(as.matrix(x), "dgCMatrix")
  } else {
    stop("Unsupported input format. Use 10X directory, .h5, .rds, .csv, .tsv, or .txt.", call. = FALSE)
  }
  if (is.list(x)) {
    preferred <- intersect(c("Gene Expression", "RNA", "gene expression"), names(x))
    x <- if (length(preferred) > 0) x[[preferred[[1]]]] else x[[1]]
  }
  x
}

