if (length(score_sets) > 0) {
  for (nm in names(score_sets)) {
    obj <- AddModuleScore(obj, features = list(score_sets[[nm]]), name = paste0(nm, "_Score"), search = FALSE)
    colnames(obj@meta.data)[ncol(obj@meta.data)] <- paste0(nm, "_Score")
  }
  score_cols <- paste0(names(score_sets), "_Score")
  cluster_scores <- obj@meta.data %>%
    tibble::rownames_to_column("cell") %>%
    group_by(cluster = .data[[cluster_col]]) %>%
    summarise(across(all_of(score_cols), mean, na.rm = TRUE), .groups = "drop")
  write_csv(cluster_scores, file.path(params$output, "tables", "cluster_module_scores.csv"))
  best_type <- apply(as.matrix(cluster_scores[, score_cols, drop = FALSE]), 1, function(x) names(score_sets)[which.max(x)])
  annotation_map <- setNames(best_type, as.character(cluster_scores$cluster))
  obj$predicted_celltype_module <- unname(annotation_map[as.character(Idents(obj))])
  p_ann <- DimPlot(obj, reduction = "umap", group.by = "predicted_celltype_module", label = TRUE, repel = TRUE) + ggtitle("Module-score cell type labels")
  save_gg(p_ann, file.path(params$output, "plots", "dimred", "08_umap_module_score_celltypes.png"), width = 9, height = 7)
  write_csv(obj@meta.data %>% tibble::rownames_to_column("cell"), file.path(params$output, "tables", "metadata_with_module_annotations.csv"))
}

