library(Seurat)
library(dplyr)
library(patchwork)

pbmc.data <- Read10X(data.dir = "./")

pbmc <- CreateSeuratObject(counts = pbmc.data, project = "pbmc2700", min.cells = 3, min.features = 200)

pbmc[["percent.mt"]] <- PercentageFeatureSet(pbmc, pattern = "^MT-")

pbmc <- subset(pbmc, subset = nFeature_RNA > 200 & nFeature_RNA < 2500 & percent.mt < 5)

pbmc <- NormalizeData(pbmc, normalization.method = "LogNormalize", scale.factor = 10000)

pbmc <- FindVariableFeatures(pbmc, selection.method = "vst", nfeatures = 2000)

all.genes <- rownames(pbmc)
pbmc <- ScaleData(pbmc, features = all.genes)

pbmc <- RunPCA(pbmc, features = VariableFeatures(object = pbmc))

pbmc <- FindNeighbors(pbmc, dims = 1:10)
pbmc <- FindClusters(pbmc, resolution = 0.5)

pbmc <- RunUMAP(pbmc, dims = 1:10)

DimPlot(pbmc, reduction = "umap", label = TRUE)

markers <- c("IL7R", "CCR7", "CD14", "LYZ", "MS4A1", "CD8A", "GNLY", "NKG7")
FeaturePlot(pbmc, features = markers)

pbmc.markers <- FindAllMarkers(pbmc, only.pos = TRUE, min.pct = 0.25, logfc.threshold = 0.25)

top10 <- pbmc.markers %>% group_by(cluster) %>% top_n(n = 10, wt = avg_log2FC)

DoHeatmap(pbmc, features = top10$gene) + NoLegend()

new.cluster.ids <- c("CD4 T cells", "CD14 Monocytes", "B cells", "CD8 T cells", 
                      "NK cells", "CD4 T cells", "CD14 Monocytes", "NK cells", "B cells")

cluster_levels <- levels(pbmc)
if (length(new.cluster.ids) != length(cluster_levels)) {
  new.cluster.ids <- rep("Unknown", length(cluster_levels))
  cluster.avg <- AverageExpression(pbmc, features = markers, group.by = "seurat_clusters")$RNA

  for (i in seq_along(cluster_levels)) {
    cl <- cluster_levels[i]
    expr <- cluster.avg[, cl]
    if (expr["CD14"] > 1 | expr["LYZ"] > 1) {
      new.cluster.ids[i] <- "CD14 Monocytes"
    } else if (expr["MS4A1"] > 1) {
      new.cluster.ids[i] <- "B cells"
    } else if (expr["GNLY"] > 1 | expr["NKG7"] > 1) {
      new.cluster.ids[i] <- "NK cells"
    } else if (expr["CD8A"] > 1) {
      new.cluster.ids[i] <- "CD8 T cells"
    } else if (expr["IL7R"] > 1 | expr["CCR7"] > 1) {
      new.cluster.ids[i] <- "CD4 T cells"
    } else {
      new.cluster.ids[i] <- "Unknown"
    }
  }
}

names(new.cluster.ids) <- cluster_levels
pbmc <- RenameIdents(pbmc, new.cluster.ids)

DimPlot(pbmc, reduction = "umap", label = TRUE, pt.size = 0.5) + NoLegend()

saveRDS(pbmc, file = "pbmc_annotated.rds")
